begin;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.actor(n integer) returns uuid language sql immutable as $$select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.failure(statement text) returns text language plpgsql as $$begin execute statement;return 'OK';exception when others then return case when sqlstate='P0001' then sqlerrm else sqlstate end;end$$;
create temp table cases(name text primary key,value jsonb);
grant all on cases to authenticated,service_role;
create function pg_temp.put(name text,value jsonb) returns void language sql as $$insert into cases values(name,value) on conflict(name) do update set value=excluded.value$$;
create function pg_temp.get(name text) returns jsonb language sql stable as $$select value from cases where cases.name=$1$$;
create function pg_temp.pid(name text) returns uuid language sql stable as $$select (pg_temp.get(name)#>>'{body,data,id}')::uuid$$;
create function pg_temp.submit(n integer,ref text) returns jsonb language sql as $$
 select public.qiyadat_payment_submit(pg_temp.actor(n),jsonb_build_object('offer_code','synthetic','payment_method','easypaisa','transaction_hash',encode(extensions.digest(ref,'sha256'),'hex')),
 'synthetic-key-'||ref,decode('01'||repeat('00',29),'hex'),encode(extensions.digest(ref,'sha256'),'hex'),'********test')$$;
create function pg_temp.decide(name text,op text default 'approve',reason text default 'OTHER') returns jsonb language sql as $$
 select public.qiyadat_payment_decide(pg_temp.actor(801),pg_temp.pid(name),op,
 case when op='approve' then '{"verification_note":"Synthetic match summary."}'::jsonb else jsonb_build_object('reason_code',reason,'message','Please check the reference.') end,
 '00000000-0000-0000-0000-000000000899')$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.actor(n),'phase6-admin-'||n||'@example.invalid','{"role":"admin"}' from generate_series(801,810)n;
insert into public.admin_users(user_id) values(pg_temp.actor(801));
insert into public.payment_offers(code,name,amount_minor,accepted_methods,instructions,active,benefits)
values('synthetic','Synthetic access',123456,array['easypaisa']::public.payment_method[],'Synthetic instructions',true,
 '{"additional_20_word_sessions":true,"session_access":"during_entitlement","reports_per_rolling_window":3,"report_window_hours":24,"saved_history_and_progress":true}');
select ok(not has_function_privilege('authenticated','public.qiyadat_admin_payments(uuid,jsonb,jsonb,integer)','EXECUTE'),'Browser cannot list admin data directly');
select ok(not has_function_privilege('authenticated','public.qiyadat_payment_decide(uuid,uuid,text,jsonb,uuid)','EXECUTE'),'Browser cannot decide');
select ok(not has_table_privilege('service_role','public.admin_audit_log','UPDATE'),'Service audit update revoked');
select ok(not has_table_privilege('service_role','public.admin_audit_log','DELETE'),'Service audit delete revoked');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
update public.app_settings set value='true' where key='payments_enabled';
select pg_temp.put('one',pg_temp.submit(802,'reference-one'));
select is(pg_temp.failure($$select public.qiyadat_admin_payments(pg_temp.actor(802))$$),'ADMIN_REQUIRED','Editable metadata cannot authorize');
update public.admin_users set active=false where user_id=pg_temp.actor(801);
select is(pg_temp.failure($$select public.qiyadat_admin_payments(pg_temp.actor(801))$$),'ADMIN_REQUIRED','Inactive admin denied');
select is(pg_temp.failure($$select pg_temp.decide('one')$$),'ADMIN_REQUIRED','Inactive admin cannot decide');
update public.admin_users set active=true where user_id=pg_temp.actor(801);
select is(jsonb_array_length(public.qiyadat_admin_payments(pg_temp.actor(801))),1,'Admin lists pending');
select is(public.qiyadat_admin_payments(pg_temp.actor(801))#>>'{0,user,id}',pg_temp.actor(802)::text,'Admin candidate identity');
select is(jsonb_array_length(public.qiyadat_admin_payments(pg_temp.actor(801),'{"status":"approved"}')),0,'Status filter');
select is(jsonb_array_length(public.qiyadat_admin_payments(pg_temp.actor(801),'{"payment_method":"jazzcash"}')),0,'Method filter');
select is(jsonb_array_length(public.qiyadat_admin_payments(pg_temp.actor(801),jsonb_build_object('transaction_hash',encode(extensions.digest('reference-one','sha256'),'hex')))),1,'Exact hash search');
select is(jsonb_array_length(public.qiyadat_admin_payments(pg_temp.actor(801),jsonb_build_object('submitted_from',private.api_time(now()+interval '1 day')))),0,'Date filter');
select is(pg_temp.failure($$select public.qiyadat_admin_payments(pg_temp.actor(801),'{"submitted_from":"2026-02-02T00:00:00Z","submitted_to":"2026-02-01T00:00:00Z"}')$$),'VALIDATION_ERROR','Reversed dates rejected');
select is(pg_temp.failure($$select public.qiyadat_admin_payments(pg_temp.actor(801),'{"unknown":1}')$$),'VALIDATION_ERROR','Unknown filters rejected');
select is(pg_temp.failure($$select public.qiyadat_admin_payments(pg_temp.actor(801),'{}',null,101)$$),'VALIDATION_ERROR','Admin limit capped');
update public.payment_offers set amount_minor=999999,active=false;
select pg_temp.put('approval',pg_temp.decide('one'));
select is(pg_temp.get('approval')->>'status','approved','Approval succeeds using inactive captured offer');
select is((select amount_minor::integer from public.payment_submissions where id=pg_temp.pid('one')),123456,'Captured price remains immutable');
select is((select access_days from public.payment_submissions where id=pg_temp.pid('one')),30,'Captured duration unchanged');
select is((select count(*)::integer from public.entitlements where payment_submission_id=pg_temp.pid('one')),1,'Exactly one entitlement');
select is(pg_temp.get('approval')#>>'{entitlement,starts_at}',pg_temp.get('approval')->>'decided_at','Initial access starts at decision time');
select ok((pg_temp.get('approval')#>>'{entitlement,expires_at}')::timestamptz=(pg_temp.get('approval')#>>'{entitlement,starts_at}')::timestamptz+interval '30 days','Exact 30-day expiry');
select is(public.qiyadat_account_context(pg_temp.actor(802))#>>'{entitlement,type}','founding_30d','Account immediately sees paid access');
select is(public.qiyadat_account_context(pg_temp.actor(802))#>>'{usage,reports_remaining_rolling_24h}','3','Paid report allowance');
select ok(private.api_has_access(pg_temp.actor(802),statement_timestamp()+interval '1 second'),'Session paid eligibility');
select is((select count(*)::integer from public.admin_audit_log where resource_id=pg_temp.pid('one')),1,'One audit');
select is((select actor_id from public.admin_audit_log where resource_id=pg_temp.pid('one')),pg_temp.actor(801),'Audit actor');
select is((select subject_id from public.admin_audit_log where resource_id=pg_temp.pid('one')),pg_temp.actor(802),'Audit candidate');
select is((select request_id from public.admin_audit_log where resource_id=pg_temp.pid('one')),'00000000-0000-0000-0000-000000000899'::uuid,'Audit request correlation');
select ok(not exists(select 1 from public.admin_audit_log where to_jsonb(admin_audit_log)::text like '%Synthetic match%' or to_jsonb(admin_audit_log)::text like '%reference-one%' or to_jsonb(admin_audit_log)::text like '%@example.invalid%'),'Audit contains no private payment text');
select is(pg_temp.failure($$update public.admin_audit_log set actor_id=pg_temp.actor(802)$$),'42501','Service cannot update audit');
select is(pg_temp.failure($$delete from public.admin_audit_log$$),'42501','Service cannot delete audit');
select is(pg_temp.failure($$select pg_temp.decide('one')$$),'PAYMENT_ALREADY_DECIDED','Repeated approval rejected');
select is(pg_temp.failure($$select pg_temp.decide('one','reject')$$),'PAYMENT_ALREADY_DECIDED','Competing rejection rejected');
update public.payment_offers set active=true;
select pg_temp.put('two',pg_temp.submit(802,'reference-two'));
select pg_temp.put('second',pg_temp.decide('two'));
select is(pg_temp.get('second')#>>'{entitlement,starts_at}',pg_temp.get('approval')#>>'{entitlement,expires_at}','Paid extension contiguous');
select is(public.qiyadat_account_context(pg_temp.actor(802))#>>'{entitlement,starts_at}',pg_temp.get('approval')#>>'{entitlement,starts_at}','Current entitlement preferred over queued future access');
select pg_temp.put('three',pg_temp.submit(802,'reference-three'));
select pg_temp.put('third',pg_temp.decide('three'));
select is(pg_temp.get('third')#>>'{entitlement,starts_at}',pg_temp.get('second')#>>'{entitlement,expires_at}','Queued future extension included');
insert into public.entitlements(user_id,type,starts_at) values(pg_temp.actor(803),'beta',now()-interval '1 day');
select pg_temp.put('beta',pg_temp.submit(803,'reference-beta'));
select pg_temp.put('beta-approval',pg_temp.decide('beta'));
select is(pg_temp.get('beta-approval')#>>'{entitlement,starts_at}',pg_temp.get('beta-approval')->>'decided_at','Beta does not extend paid start');
select is((select count(*)::integer from public.entitlements where user_id=pg_temp.actor(803) and type='beta'),1,'Beta unchanged');
select pg_temp.put('reject',pg_temp.submit(804,'reference-rejected'));
select pg_temp.put('rejection',pg_temp.decide('reject','reject','AMOUNT_MISMATCH'));
select is(pg_temp.get('rejection')->>'status','rejected','Rejection final');
select is((select count(*)::integer from public.entitlements where user_id=pg_temp.actor(804)),0,'No rejection entitlement');
select is(pg_temp.get('rejection')#>>'{rejection,reason_code}','AMOUNT_MISMATCH','Candidate reason');
select is(pg_temp.submit(805,'reference-rejected')->>'error_code','TRANSACTION_ID_EXISTS','Rejected hash stays reserved');
select is(pg_temp.submit(804,'reference-replacement')->>'status','201','Rejected candidate may submit a different reference');
select is(pg_temp.failure($$select pg_temp.decide('reject')$$),'PAYMENT_ALREADY_DECIDED','Rejected payment cannot approve');
select is(pg_temp.failure($$select public.qiyadat_payment_decide(pg_temp.actor(801),gen_random_uuid(),'approve','{"verification_note":"Matched."}',gen_random_uuid())$$),'NOT_FOUND','Unknown payment hidden');
reset role;
select is(pg_temp.failure($$update public.admin_audit_log set actor_id=pg_temp.actor(802)$$),'23514','Even table owner cannot update immutable audit');
select is(pg_temp.failure($$delete from public.admin_audit_log$$),'23514','Even table owner cannot delete immutable audit');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000802"}',true);
set local role authenticated;
select is(jsonb_array_length(public.qiyadat_payment_history(null,1)),2,'History reads limit plus lookahead');
select is(public.qiyadat_payment_history()#>>'{0,entitlement,type}','founding_30d','Candidate entitlement projection');
select ok(not (public.qiyadat_payment_history()->0?'verification_note'),'Note remains private');
reset role;
select * from finish();
rollback;
